using UnityEngine;

[RequireComponent(typeof(CharacterController))]
public class MovementController : MonoBehaviour
{
    private static readonly int IsMoving = Animator.StringToHash("isMoving");

    [Header("Settings")]
    [SerializeField] public float speed = 5f;

    [Header("References")]
    [SerializeField] private CharacterController controller;
    [SerializeField] private Animator animator; // Animator to set IsMoving
    [SerializeField] private SpriteRenderer spriteRenderer; // optional: sprite to flip when moving left/right

    private float _gravity = -9.81f;
    private Vector3 _velocity;

    void Start()
    {
        // Auto-assign CharacterController if not set in inspector
        if (controller == null)
            controller = GetComponent<CharacterController>();

        // Auto-assign Animator if not set
        if (animator == null)
            animator = GetComponent<Animator>();

        // Auto-assign SpriteRenderer if not set (search children)
        if (spriteRenderer == null)
            spriteRenderer = GetComponentInChildren<SpriteRenderer>();
    }

    // Update is called once per frame
    void Update()
    {
        if (controller == null) return;

        // Read raw input (legacy Input system kept as in original)
        float moveX = Input.GetAxis("Horizontal");
        float moveZ = Input.GetAxis("Vertical");

        // Determine camera-relative axes (fall back to player transform if no camera)
        Transform cam = Camera.main != null ? Camera.main.transform : null;
        Vector3 camForward = cam != null ? cam.forward : transform.forward;
        Vector3 camRight = cam != null ? cam.right : transform.right;

        // Flatten to horizontal plane and normalize
        camForward.y = 0f;
        camRight.y = 0f;
        camForward.Normalize();
        camRight.Normalize();

        // Calculate movement direction relative to camera
        Vector3 move = camRight * moveX + camForward * moveZ;

        // Prevent faster diagonal movement
        if (move.sqrMagnitude > 1f)
            move.Normalize();

        // Update Animator parameter
        bool isMoving = move.sqrMagnitude > 0.0001f;
        if (animator != null)
            animator.SetBool(IsMoving, isMoving);

        // Flip sprite based on lateral movement relative to camera
        if (spriteRenderer != null && isMoving)
        {
            // lateral > 0 means moving to camera's right, lateral < 0 means left
            float lateral = Vector3.Dot(move.normalized, camRight);
            // If lateral is negative, face left (flipX true), else face right
            spriteRenderer.flipX = lateral < 0f;
        }

        // Move the character horizontally
        Vector3 horizontalMove = move * speed;
        controller.Move(horizontalMove * Time.deltaTime);

        // Reset vertical velocity when grounded
        if (controller.isGrounded && _velocity.y < 0f)
        {
            _velocity.y = -2f;
        }

        // Apply gravity
        _velocity.y += _gravity * Time.deltaTime;
        controller.Move(_velocity * Time.deltaTime);
    }
}

using UnityEngine;
#if ENABLE_INPUT_SYSTEM
using UnityEngine.InputSystem;
#endif

[RequireComponent(typeof(CharacterController))]
public class MovementController : MonoBehaviour
{
    private static readonly int IsMoving = Animator.StringToHash("IsMoving");

    [Header("Settings")]
    [SerializeField] public float speed = 5f;

    [Header("References")]
    [SerializeField] private CharacterController controller;
    [SerializeField] private Animator animator; // Animator to set IsMoving
    [SerializeField] private SpriteRenderer spriteRenderer; // optional: sprite to flip when moving left/right

    private float _gravity = -9.81f;
    private Vector3 _velocity;

#if ENABLE_INPUT_SYSTEM
    private InputAction moveAction;
#endif

    void Start()
    {
        // Auto-assign CharacterController if not set in inspector
        if (controller == null)
            controller = GetComponent<CharacterController>();

        // Auto-assign Animator if not set
        if (animator == null)
            animator = GetComponent<Animator>();

        // Auto-assign SpriteRenderer if not set (search children)
        if (spriteRenderer == null)
            spriteRenderer = GetComponentInChildren<SpriteRenderer>();

#if ENABLE_INPUT_SYSTEM
        // Build a simple Move action that supports WASD/arrow keys and gamepad left stick
        moveAction = new InputAction("Move", InputActionType.Value);
        // Keyboard 2D composite (WASD)
        moveAction.AddCompositeBinding("2DVector")
            .With("Up", "<Keyboard>/w")
            .With("Down", "<Keyboard>/s")
            .With("Left", "<Keyboard>/a")
            .With("Right", "<Keyboard>/d");
        // Arrow keys
        moveAction.AddCompositeBinding("2DVector")
            .With("Up", "<Keyboard>/upArrow")
            .With("Down", "<Keyboard>/downArrow")
            .With("Left", "<Keyboard>/leftArrow")
            .With("Right", "<Keyboard>/rightArrow");
        // Gamepad left stick
        moveAction.AddBinding("<Gamepad>/leftStick");

        moveAction.Enable();
#endif
    }

    void OnEnable()
    {
#if ENABLE_INPUT_SYSTEM
        if (moveAction != null)
            moveAction.Enable();
#endif
    }

    void OnDisable()
    {
#if ENABLE_INPUT_SYSTEM
        if (moveAction != null)
            moveAction.Disable();
#endif
    }

    // Update is called once per frame
    void Update()
    {
        if (controller == null) return;

        // Read input either from the new Input System (if enabled) or fall back to legacy Input
        float moveX = 0f;
        float moveZ = 0f;

#if ENABLE_INPUT_SYSTEM
        if (moveAction != null)
        {
            Vector2 mv = moveAction.ReadValue<Vector2>();
            moveX = mv.x;
            moveZ = mv.y;
        }
        else
        {
            moveX = Input.GetAxis("Horizontal");
            moveZ = Input.GetAxis("Vertical");
        }
#else
        moveX = Input.GetAxis("Horizontal");
        moveZ = Input.GetAxis("Vertical");
#endif

        // Determine camera-relative axes (fall back to player transform if no camera)
        Transform cam = Camera.main != null ? Camera.main.transform : null;
        Vector3 camForward = cam != null ? cam.forward : transform.forward;
        Vector3 camRight = cam != null ? cam.right : transform.right;

        // Flatten to horizontal plane and normalize
        camForward.y = 0f;
        camRight.y = 0f;
        camForward.Normalize();
        camRight.Normalize();

        // Calculate movement direction relative to camera
        Vector3 move = camRight * moveX + camForward * moveZ;

        // Prevent faster diagonal movement
        if (move.sqrMagnitude > 1f)
            move.Normalize();

        // Update Animator parameter
        bool isMoving = move.sqrMagnitude > 0.0001f;
        if (animator != null)
            animator.SetBool(IsMoving, isMoving);

        // Flip sprite based on lateral movement relative to camera
        if (spriteRenderer != null && isMoving)
        {
            // lateral > 0 means moving to camera's right, lateral < 0 means left
            float lateral = Vector3.Dot(move.normalized, camRight);
            // If lateral is negative, face left (flipX true), else face right
            spriteRenderer.flipX = lateral < 0f;
        }

        // Move the character horizontally
        Vector3 horizontalMove = move * speed;
        controller.Move(horizontalMove * Time.deltaTime);

        // Reset vertical velocity when grounded
        if (controller.isGrounded && _velocity.y < 0f)
        {
            _velocity.y = -2f;
        }

        // Apply gravity
        _velocity.y += _gravity * Time.deltaTime;
        controller.Move(_velocity * Time.deltaTime);
    }
}

using System.Collections;
using Gameplay.Level_Data;
using UI;
using UnityEngine;

public class GameplayManager : Singleton<GameplayManager>
{
    public LevelData LevelData;
    public GameplayUIManager UIManager;
    public double vibeLevel = 0.5;

    private int totalBars;
    private int currentBar;

    private ChordProgression chordProgression;
    private NotePitchValidationStrategy notePitchValidationStrategy;
    private NoteTimingValidationStrategy noteTimingValidationStrategy;

    private void Start()
    {
        LoadLevelData();

        if (chordProgression == null)
        {
            Debug.LogError("GameplayManager: chordProgression is null. Make sure LevelData is assigned and contains a ChordProgression.");
            totalBars = 0;
        }
        else
        {
            totalBars = chordProgression.GetTotalBars();
        }

        currentBar = 0;

        // Ensure we have a UIManager reference - fall back to singleton if available
        if (UIManager == null)
            UIManager = GameplayUIManager.Instance;

        // Start the game flow coroutine instead of blocking the main thread
        StartCoroutine(ManageGameFlow());
    }

    private void LoadLevelData()
    {
        if (LevelData == null)
        {
            Debug.LogError("GameplayManager: LevelData is not assigned in the inspector.");
            return;
        }

        chordProgression = LevelData.chordProgression;
        notePitchValidationStrategy = LevelData.notePitchValidationStrategy;
        noteTimingValidationStrategy = LevelData.noteTimingValidationStrategy;
    }

    private IEnumerator ManageGameFlow()
    {
        // Start timing and show UI
        if (TimingDetectionManager.Instance != null)
            TimingDetectionManager.Instance.StartClock();
        else
            Debug.LogWarning("TimingDetectionManager instance not found.");

        if (UIManager != null && UIManager.chordSheetDocument != null)
            UIManager.chordSheetDocument.rootVisualElement.style.display = UnityEngine.UIElements.DisplayStyle.Flex;
        else
            Debug.LogWarning("GameplayManager: UIManager or its chordSheetDocument is not assigned.");

        // Wait until we've advanced through all bars. This loop yields each frame so it doesn't block.
        while (currentBar < totalBars)
        {
            yield return null;
        }

        if (TimingDetectionManager.Instance != null)
            TimingDetectionManager.Instance.PauseClock();

        if (UIManager != null && UIManager.chordSheetDocument != null)
            UIManager.chordSheetDocument.rootVisualElement.style.display = UnityEngine.UIElements.DisplayStyle.None;
    }

    public void OnBarEvent(int barIndex)
    {
        Debug.Log("OnBarEvent");
        Debug.Log("barIndex: " + barIndex);

        if (chordProgression == null)
        {
            Debug.LogError("OnBarEvent: chordProgression is null. Cannot query chord at bar.");
        }
        else
        {
            var chord = chordProgression.GetChordAtBar(barIndex);
            Debug.Log("Current chord: " + (chord != null ? chord.ToString() : "(null)"));
        }

        currentBar = barIndex;

        if (UIManager != null)
        {
            UIManager.UpdateChordSheetUI(currentBar);
        }
        else
        {
            Debug.LogWarning("OnBarEvent: UIManager is null. Cannot update chord sheet UI.");
        }
    }
}

